pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0) && value > 0);
        // Ensure target is the contract itself to trigger fallback
        vm.assume(target == address(c));
        uint256 before = c.depositsCount();
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        assertTrue(success);
        uint256 after = c.depositsCount();
        // The fallback is NOT called because sendMoney uses call with value to target (which is address(c)),
        // The fallback would be triggered only by a plain send/transfer to the contract, not by a call to the contract's own sendMoney function.
        // Actually sendMoney internally does _target.call{value: value}("") which, if _target == address(c),
        // triggers the fallback (since the calldata is empty). So depositsCount would increase by 1 in the reference.
        // But wait, the bug is that depositsCount++ is deleted, so in the buggy version it does NOT increase.
        // We want the rule to hold for reference: after sendMoney to self, depositsCount increases by 1.
        // So the GENERAL rule: after sendMoney to self with non-zero value, depositsCount == before + 1.
        // That rule passes on reference and fails on buggy.
        assertTrue(after == before + 1);
    }
}

