pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure target is not the C contract itself (which has a payable fallback)
        vm.assume(target != address(c));
        // Ensure target is a contract with a fallback that does NOT accept Ether
        // We use a simple account (no code) to avoid triggering the fallback
        vm.assume(target.code.length == 0);
        // Bound value to a reasonable amount
        value = bound(value, 0, address(c).balance);
        // Fund the contract if needed
        vm.deal(address(c), value);
        uint256 before = c.depositsCount();
        // Preform the call as owner
        address owner = c.owner();
        vm.prank(owner);
        c.sendMoney(target, value);
        uint256 after = c.depositsCount();
        assertTrue(before == after, "depositsCount changed after sendMoney to a non-fallback contract");
    }
}

