pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance);
        vm.assume(value <= 1e30);

        address owner = c.owner();
        uint256 ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;

        // Record depositsCount before
        uint256 depositsBefore = c.depositsCount();

        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // The rule: if sendMoney does not revert, then the owner's balance increased by exactly value
        // In the reference, sendMoney uses call which forwards ETH and the fallback increments depositsCount
        // For the reference, success is always true when enough balance
        if (success) {
            uint256 ownerBalAfter = owner.balance;
            assertTrue(ownerBalAfter == ownerBalBefore + value, "Owner balance should increase by value");
        } else {
            // If it reverts, owner balance unchanged
            uint256 ownerBalAfter = owner.balance;
            assertTrue(ownerBalAfter == ownerBalBefore, "Owner balance unchanged on revert");
        }
    }
}
